package com.pratik.imagetap;
import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w412dp-h892dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ReviewUiTest {
 @Test public void optionsRoundTripAndActiveSubset()throws Exception{
  Context c=RuntimeEnvironment.getApplication();Bitmap b=Bitmap.createBitmap(24,24,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);File f=TargetStore.save(c,b);TargetOptions original=new TargetOptions(false,709,new RegionRules.Region(.7f,0,1,.35f,75),"Close only");original.save(c,f);TargetOptions loaded=TargetOptions.load(c,f);assertFalse(loaded.enabled);assertEquals(709,loaded.sourceWidth);assertEquals("Close only",loaded.name);assertEquals(.7f,loaded.area.left,.001);assertEquals(2,loaded.scale(1418),0);assertFalse(TargetStore.activeFiles(c).contains(f));new TargetOptions(true,709,loaded.area,loaded.name).save(c,f);assertTrue(TargetStore.activeFiles(c).contains(f));assertTrue(f.isFile());b.recycle();
 }
 @Test public void corruptOptionsDisableTarget(){Context c=RuntimeEnvironment.getApplication();File f=new File("broken.png");c.getSharedPreferences("target-options",0).edit().putString(f.getName(),"invalid json").commit();assertFalse(TargetOptions.load(c,f).enabled);}
 @Test public void invalidWidthRejected(){try{new TargetOptions(true,25,null,"");fail("Must not use icon width as source resolution");}catch(IllegalArgumentException expected){} }
 @Test public void failedImageWriteDoesNotLeavePartialTarget()throws Exception{
  Context c=RuntimeEnvironment.getApplication();int before=TargetStore.files(c).size();Bitmap b=Bitmap.createBitmap(24,24,Bitmap.Config.ARGB_8888);b.recycle();try{TargetStore.save(c,b);fail("Recycled image must fail");}catch(IOException expected){}assertEquals(before,TargetStore.files(c).size());for(File f:TargetStore.folder(c).listFiles())assertFalse(f.getName().endsWith(".tmp"));
 }
 @Test public void cropSurvivesActivityRecreation()throws Exception{
  org.robolectric.android.controller.ActivityController<MainActivity> ctl=Robolectric.buildActivity(MainActivity.class).setup();MainActivity a=ctl.get();Bitmap b=Bitmap.createBitmap(60,40,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);Method show=MainActivity.class.getDeclaredMethod("showCrop",Bitmap.class);show.setAccessible(true);show.invoke(a,b);Field field=MainActivity.class.getDeclaredField("activeCrop");field.setAccessible(true);CropView crop=(CropView)field.get(a);crop.selection.set(10,5,50,35);Path erase=new Path();erase.moveTo(20,10);erase.lineTo(20,30);crop.edits.add(new CropView.MaskEdit(erase,"Erase",6));ctl.recreate();CropView restored=(CropView)field.get(ctl.get());assertNotNull(restored);assertEquals(1,restored.edits.size());Bitmap out=restored.crop();assertEquals(40,out.getWidth());assertEquals(0,Color.alpha(out.getPixel(10,15)));out.recycle();ctl.pause().stop().destroy();
 }
 @Test public void optionsDialogSavesAndRenders()throws Exception{
  MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();Bitmap b=Bitmap.createBitmap(24,24,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);File f=TargetStore.save(a,b);TargetEditor.open(a,f,()->{});Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();android.app.AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();View root=dialog.getWindow().getDecorView();find(root,"Top right").performClick();Switch active=(Switch)find(root,"Include in scans");active.setChecked(false);dialog.getButton(-1).performClick();TargetOptions loaded=TargetOptions.load(a,f);assertFalse(loaded.enabled);assertEquals(.65f,loaded.area.left,.001);a.finish();b.recycle();
 }
 static View find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View match=find(((ViewGroup)v).getChildAt(i),text);if(match!=null)return match;}return null;}
}
